"""Insert a Node in a Doubly Linked List — four pointer updates.

Order matters: wire the new node's own links first, then patch the neighbours,
so nothing is lost mid-update.

Time: O(position)   Space: O(1) beyond the list
"""
from typing import List


class _Node:
    __slots__ = ("val", "prev", "next")

    def __init__(self, val):
        self.val = val
        self.prev = None
        self.next = None


def _build(values):
    head = tail = None
    for value in values:
        node = _Node(value)
        if head is None:
            head = tail = node
        else:
            tail.next = node
            node.prev = tail
            tail = node
    return head


def _dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


class Solution:
    def insertAfter(self, values: List[int], position: int, val: int) -> List[int]:
        head = _build(values)
        fresh = _Node(val)

        if position == -1:
            fresh.next = head
            if head:
                head.prev = fresh
            return _dump(fresh)

        node = head
        for _ in range(position):
            if node is None:
                return values
            node = node.next
        if node is None:
            return values

        fresh.prev = node
        fresh.next = node.next
        if node.next:
            node.next.prev = fresh
        node.next = fresh
        return _dump(head)
